/*
 * CSS and TTML style helpers for subtitle rendering.
 */

import { parseTTMLColor, parseTTMLLength, parseTTMLLengthPair } from './ttml.js';

export const DEFAULT_ARIB_FONT_STACK = '"Hiragino Maru Gothic Pro", "BIZ UDGothic", "Yu Gothic Medium", sans-serif';

export function applyTTMLBorder(element, style, scale) {
    if (!element || !style) {
        return;
    }
    if (style.border) {
        element.style.border = scaleTTMLBorder(style.border, scale);
    }
    if (style.borderTop) {
        element.style.borderTop = scaleTTMLBorder(style.borderTop, scale);
    }
    if (style.borderBottom) {
        element.style.borderBottom = scaleTTMLBorder(style.borderBottom, scale);
    }
    if (style.borderLeft) {
        element.style.borderLeft = scaleTTMLBorder(style.borderLeft, scale);
    }
    if (style.borderRight) {
        element.style.borderRight = scaleTTMLBorder(style.borderRight, scale);
    }
    element.style.boxDecorationBreak = 'clone';
    element.style.webkitBoxDecorationBreak = 'clone';
}

export function scaleTTMLBorder(value, scale) {
    const parts = splitStyleTokens(value);
    if (parts.length < 3) {
        return value;
    }
    const width = parseTTMLLength(parts[1], 3840);
    const scaledWidth = width === null ? parts[1] : Math.max(1, width * scale) + 'px';
    return parts[0] + ' ' + scaledWidth + ' ' + parseTTMLColor(parts.slice(2).join(' '));
}

export function applyTextStroke(element, width, color) {
    const strokeWidth = Math.max(1, width);
    element.style.webkitTextStroke = strokeWidth + 'px ' + color;
    element.style.paintOrder = 'stroke fill';
    element.style.setProperty('--aribb62-stroke-color', color);
    element.style.setProperty('--aribb62-stroke-width', strokeWidth + 'px');
    element.style.textShadow = 'none';
}

export function getTextStrokeWidth(element) {
    const value = element && element.style ? element.style.getPropertyValue('--aribb62-stroke-width') : '';
    const width = parseFloat(value);
    return Number.isFinite(width) ? width : 0;
}

export function parseTTMLTextStroke(value, scale) {
    const parts = splitStyleTokens(value);
    const lowerParts = parts.map((part) => part.toLowerCase());
    if (parts.length === 0 || lowerParts.indexOf('none') >= 0 || lowerParts.indexOf('hidden') >= 0) {
        return null;
    }

    let width = null;
    let blur = null;
    const colorParts = [];

    parts.forEach((part) => {
        const parsedLength = parseTTMLLength(part, 3840);
        if (parsedLength !== null && width === null) {
            width = parsedLength;
            return;
        }
        if (parsedLength !== null && blur === null) {
            blur = parsedLength;
            return;
        }
        colorParts.push(part);
    });

    if (width === null || width <= 0) {
        return null;
    }

    return {
        width: width * scale,
        blur: Math.max(0, (blur || 0) * scale),
        color: colorParts.length > 0 ? parseTTMLColor(colorParts.join(' ')) : 'currentColor'
    };
}

export function scaleTTMLShadow(value, scale) {
    const parts = splitStyleTokens(value);
    if (parts.length < 4) {
        return value;
    }
    const x = parseTTMLLength(parts[0], 3840);
    const y = parseTTMLLength(parts[1], 2160);
    const blur = parseTTMLLength(parts[2], 3840);
    if (x === null || y === null || blur === null) {
        return value;
    }
    return [
        (x * scale) + 'px',
        (y * scale) + 'px',
        (blur * scale) + 'px',
        parseTTMLColor(parts.slice(3).join(' '))
    ].join(' ');
}

export function parseARIBAnimation(value, animationNames) {
    const parts = splitStyleTokens(value);
    if (parts[2] && /^steps\(/.test(parts[2]) && !/\)$/.test(parts[2]) && parts[3]) {
        parts.splice(2, 2, (parts[2] + parts[3]).replace(/\s+/g, ''));
    }
    if (parts.length < 6 || !isSafeCssIdentifier(parts[0])) {
        return '';
    }
    const animationName = animationNames && animationNames[parts[0]] ? animationNames[parts[0]] : parts[0];
    return [
        animationName,
        cssTime(parts[1]),
        cssTimingFunction(parts[2]),
        cssTime(parts[3]),
        parts[4],
        cssAnimationDirection(parts[5]),
        'both'
    ].join(' ');
}

export function applyARIBMarquee(element, value, writingMode) {
    const parts = splitStyleTokens(value);
    if (parts.length < 4) {
        return;
    }
    const style = parts[0];
    const direction = parts[1] === 'reverse' ? 'reverse' : 'forward';
    const speed = parts[2];
    const count = parts[3] === 'infinite' ? 'infinite' : String(Math.max(1, Number(parts[3]) || 1));
    const duration = speed === 'slow' ? '16s' : (speed === 'fast' ? '6s' : '10s');
    element.style.display = element.style.display || 'inline-block';
    element.style.whiteSpace = 'pre';
    const axis = /^(?:tblr|tbrl|vertical-lr|vertical-rl)$/.test(String(writingMode || '')) ? 'y' : 'x';
    element.style.animationName = [
        'aribb62-marquee',
        style === 'slide' || style === 'alternate' ? style : 'scroll',
        axis,
        direction
    ].join('-');
    element.style.animationDuration = duration;
    element.style.animationTimingFunction = 'linear';
    element.style.animationIterationCount = count;
    element.style.animationFillMode = style === 'scroll' ? 'none' : 'forwards';
    element.style.animationDirection = 'normal';
}

export function mapDisplayAlign(value) {
    switch (value) {
        case 'center':
            return 'center';
        case 'after':
            return 'flex-end';
        case 'before':
        default:
            return 'flex-start';
    }
}

export function mapTextAlignItems(value) {
    switch (value) {
        case 'end':
        case 'right':
            return 'flex-end';
        case 'left':
        case 'start':
            return 'flex-start';
        default:
            return 'center';
    }
}

export function mapWritingMode(value) {
    switch (value) {
        case 'lrtb':
        case 'horizontal-tb':
            return { writingMode: 'horizontal-tb', direction: 'ltr' };
        case 'rltb':
            return { writingMode: 'horizontal-tb', direction: 'rtl' };
        case 'tblr':
        case 'vertical-lr':
            return { writingMode: 'vertical-lr', direction: '' };
        case 'tbrl':
        case 'vertical-rl':
            return { writingMode: 'vertical-rl', direction: '' };
        default:
            return { writingMode: '', direction: '' };
    }
}

export function mapARIBFontFamily(value) {
    const text = String(value || '').trim();
    const normalized = text.replace(/^['"]|['"]$/g, '');
    switch (normalized) {
        case '丸ゴシック':
            return mergeFontFamilyStacks('"Hiragino Maru Gothic Pro", "HGMaruGothicMPRO"', DEFAULT_ARIB_FONT_STACK);
        case '太丸ゴシック':
            return mergeFontFamilyStacks('"Hiragino Maru Gothic Pro", "HGMaruGothicMPRO"', DEFAULT_ARIB_FONT_STACK);
        case '角ゴシック':
            return mergeFontFamilyStacks('"Yu Gothic", "Hiragino Kaku Gothic ProN", "Meiryo"', DEFAULT_ARIB_FONT_STACK);
        case 'default':
        case 'sansSerif':
        case 'sans-serif':
            return DEFAULT_ARIB_FONT_STACK;
        default:
            return text;
    }
}

export function mergeFontFamilyStacks(primary, fallback) {
    const families = [];
    const seen = {};
    splitFontFamilyList(primary).concat(splitFontFamilyList(fallback)).forEach((family) => {
        const key = family.replace(/^['"]|['"]$/g, '').toLowerCase();
        if (!key || seen[key]) {
            return;
        }
        seen[key] = true;
        families.push(family);
    });
    return families.join(', ');
}

export function splitFontFamilyList(value) {
    const families = [];
    let current = '';
    let quote = '';
    String(value || '').split('').forEach((char) => {
        if (quote) {
            current += char;
            if (char === quote) {
                quote = '';
            }
            return;
        }
        if (char === '"' || char === "'") {
            quote = char;
            current += char;
            return;
        }
        if (char === ',') {
            const family = current.trim();
            if (family) {
                families.push(family);
            }
            current = '';
            return;
        }
        current += char;
    });
    const family = current.trim();
    if (family) {
        families.push(family);
    }
    return families;
}

export function fontFaceFamilyStackForText(fontFaces, text) {
    if (!fontFaces || fontFaces.length === 0 || !text) {
        return '';
    }

    const families = [];
    const seen = {};
    fontFaces.forEach((fontFace) => {
        if (!fontFace.family || seen[fontFace.family]) {
            return;
        }
        if (fontFace.unicodeRange && !textMatchesUnicodeRange(text, fontFace.unicodeRange)) {
            return;
        }
        seen[fontFace.family] = true;
        families.push('"' + cssEscapeString(fontFace.family) + '"');
    });
    return families.join(', ');
}

export function fontFaceMatchesText(fontFace, text) {
    return !!fontFace && (!fontFace.unicodeRange || textMatchesUnicodeRange(text, fontFace.unicodeRange));
}

export function createFontFaceStyleElement(fontFaces) {
    const styleElement = document.createElement('style');
    styleElement.textContent = fontFaces.map((fontFace) => {
        const parts = [
            'font-family: "' + cssEscapeString(fontFace.family) + '"',
            'src: url("' + cssEscapeUrl(fontFace.url) + '")' + (fontFace.format ? ' format("' + cssEscapeString(fontFace.format) + '")' : '')
        ];
        if (fontFace.unicodeRange) {
            parts.push('unicode-range: ' + fontFace.unicodeRange);
        }
        return '@font-face { ' + parts.join('; ') + '; }';
    }).join('\n');
    return styleElement;
}

export function createCueStyleElement(cue, scale, animationNames) {
    const styleElement = document.createElement('style');
    const css = [];

    if (cue.fontFaces && cue.fontFaces.length > 0) {
        cue.fontFaces.forEach((fontFace) => {
            const parts = [
                'font-family: "' + cssEscapeString(fontFace.family) + '"',
                'src: url("' + cssEscapeUrl(fontFace.url) + '")' + (fontFace.format ? ' format("' + cssEscapeString(fontFace.format) + '")' : '')
            ];
            if (fontFace.unicodeRange) {
                parts.push('unicode-range: ' + fontFace.unicodeRange);
            }
            css.push('@font-face { ' + parts.join('; ') + '; }');
        });
    }

    if (cue.keyframes && cue.keyframes.length > 0) {
        cue.keyframes.forEach((keyframes) => {
            if (!keyframes.name || !isSafeCssIdentifier(keyframes.name) || keyframes.frames.length === 0) {
                return;
            }
            const frames = keyframes.frames.map((frame) => {
                const declarations = keyframeStyleToCSS(frame.style, scale);
                return frame.position + ' { ' + declarations.join('; ') + '; }';
            });
            const animationName = animationNames && animationNames[keyframes.name] ?
                animationNames[keyframes.name] : keyframes.name;
            css.push('@keyframes ' + animationName + ' { ' + frames.join(' ') + ' }');
        });
    }

    if (cue.hasMarquee) {
        appendMarqueeKeyframes(css, 'x', 'translateX');
        appendMarqueeKeyframes(css, 'y', 'translateY');
    }

    styleElement.textContent = css.join('\n');
    return styleElement;
}

function appendMarqueeKeyframes(css, axis, transform) {
    css.push('@keyframes aribb62-marquee-scroll-' + axis + '-forward { from { transform: ' + transform + '(-100%); } to { transform: ' + transform + '(100%); } }');
    css.push('@keyframes aribb62-marquee-scroll-' + axis + '-reverse { from { transform: ' + transform + '(100%); } to { transform: ' + transform + '(-100%); } }');
    css.push('@keyframes aribb62-marquee-slide-' + axis + '-forward { from { transform: ' + transform + '(-100%); } to { transform: ' + transform + '(0); } }');
    css.push('@keyframes aribb62-marquee-slide-' + axis + '-reverse { from { transform: ' + transform + '(100%); } to { transform: ' + transform + '(0); } }');
    css.push('@keyframes aribb62-marquee-alternate-' + axis + '-forward { 0%, 100% { transform: ' + transform + '(-100%); } 50% { transform: ' + transform + '(100%); } }');
    css.push('@keyframes aribb62-marquee-alternate-' + axis + '-reverse { 0%, 100% { transform: ' + transform + '(100%); } 50% { transform: ' + transform + '(-100%); } }');
}

export function keyframeStyleToCSS(style, scale) {
    const declarations = [];
    if (style.backgroundColor) {
        declarations.push('background-color: ' + parseTTMLColor(style.backgroundColor));
    }
    if (style.color) {
        declarations.push('color: ' + parseTTMLColor(style.color));
    }
    if (style.fontSize) {
        const pair = parseTTMLLengthPair(style.fontSize, [3840, 2160]);
        const height = pair ? pair[1] : parseTTMLLength(style.fontSize, 2160);
        if (height !== null) {
            declarations.push('font-size: ' + height * scale + 'px');
        }
    }
    if (style.extent) {
        const extent = parseTTMLLengthPair(style.extent, [3840, 2160]);
        if (extent) {
            declarations.push('width: ' + (extent[0] * scale) + 'px');
            declarations.push('height: ' + (extent[1] * scale) + 'px');
        }
    }
    if (style.opacity) {
        declarations.push('opacity: ' + style.opacity);
    }
    if (style.origin) {
        const origin = parseTTMLLengthPair(style.origin, [3840, 2160]);
        if (origin) {
            declarations.push(
                'transform: translate(calc(' + (origin[0] * scale) +
                'px - var(--aribb62-origin-x, 0px)), calc(' + (origin[1] * scale) +
                'px - var(--aribb62-origin-y, 0px)))'
            );
        }
    }
    return declarations;
}

export function cssEscapeUrl(value) {
    return String(value || '').replace(/["\\\n\r]/g, '\\$&');
}

export function cssEscapeString(value) {
    return String(value || '').replace(/["\\\n\r]/g, '\\$&');
}

export function splitStyleTokens(value) {
    return String(value || '').trim().match(/"[^"]*"|'[^']*'|\S+/g) || [];
}

export function isSafeCssIdentifier(value) {
    return /^-?[_a-zA-Z][_a-zA-Z0-9-]*$/.test(String(value || ''));
}

export function cssTime(value) {
    return /^(?:[0-9.]+m?s|0)$/.test(String(value || '')) ? String(value) : '0ms';
}

export function cssTimingFunction(value) {
    const text = String(value || '');
    if (/^(ease|linear|ease-in|ease-out|ease-in-out|step-start|step-end)$/.test(text)) {
        return text;
    }
    if (/^steps\([0-9]+,(?:start|end)\)$/.test(text.replace(/\s+/g, ''))) {
        return text.replace(/\s+/g, '');
    }
    return 'linear';
}

export function cssAnimationDirection(value) {
    return value === 'alternate' ? 'alternate' : 'normal';
}

function textMatchesUnicodeRange(text, unicodeRange) {
    const chars = Array.from(String(text || ''));
    for (let i = 0; i < chars.length; i++) {
        if (codePointMatchesUnicodeRange(chars[i].codePointAt(0), unicodeRange)) {
            return true;
        }
    }
    return false;
}

function codePointMatchesUnicodeRange(codePoint, unicodeRange) {
    const ranges = String(unicodeRange || '').split(',');
    for (let i = 0; i < ranges.length; i++) {
        const range = ranges[i].trim();
        const match = range.match(/^U\+([0-9A-F?]+)(?:-([0-9A-F]+))?$/i);
        if (!match) {
            continue;
        }
        let start = match[1].toUpperCase();
        const end = match[2];
        if (start.indexOf('?') >= 0) {
            const min = parseInt(start.replace(/\?/g, '0'), 16);
            const max = parseInt(start.replace(/\?/g, 'F'), 16);
            if (codePoint >= min && codePoint <= max) {
                return true;
            }
            continue;
        }

        const min = parseInt(start, 16);
        const max = end ? parseInt(end, 16) : min;
        if (codePoint >= min && codePoint <= max) {
            return true;
        }
    }
    return false;
}
